/**
 * @name Unsafe deserialization from function argument
 * @description Deserializing data from a function argument using pickle can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-deserialization-arg
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PickleInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember(["load", "loads"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PickleInjectionFlow = TaintTracking::Global<PickleInjectionConfig>;
import PickleInjectionFlow::PathGraph

from PickleInjectionFlow::PathNode source, PickleInjectionFlow::PathNode sink
where PickleInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe deserialization from $@.", source.getNode(), "function argument"

/**
 * @name Regex Injection
 * @description User input used in regular expressions can lead to ReDoS or logic bypass.
 * @kind path-problem
 * @problem.severity error
 * @id py/regex-injection
 * @tags security
 *       external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module RegexInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource or
    // Also consider function arguments as potential sources for a library
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("re").getMember(["compile", "search", "match", "fullmatch", "split", "findall", "finditer", "sub", "subn"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module RegexInjectionFlow = TaintTracking::Global<RegexInjectionConfig>;
import RegexInjectionFlow::PathGraph

from RegexInjectionFlow::PathNode source, RegexInjectionFlow::PathNode sink
where RegexInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Regex constructed from $@.", source.getNode(), "user input"

/**
 * @name Path traversal
 * @description Accessing files using user-controlled paths can allow attackers to access sensitive files.
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *       external/cwe/cwe-022
 *       external/cwe/cwe-023
 *       external/cwe/cwe-036
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Function arguments as sources to catch library-level issues
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"
